import numpy as np, torch, model, os
print(os.listdir(model.HERE))
mem=[9, 10, 19, 46, 49, 51, 54]
torch.manual_seed(0)
cs=np.linspace(0.025,0.975,20)
xi=torch.randn(512*20,2); cc=torch.tensor(np.repeat(cs,512),dtype=torch.float32)
nets={'v1':model.load()}
for f in os.listdir(model.HERE):
    if f.endswith('.pt') and f!='weights.pt': print('extra',f)
try:
    nets['v0']=model.load(os.path.join(model.HERE,'..','weights_v0.pt'))
except Exception as e: print('nov0',e)
for ver,net in nets.items():
    a=model.decode(net,xi,cc).numpy()
    bad=np.zeros(len(a),bool)
    for i in mem: bad|=model.in_basin(i,a)
    print(ver,'overall',bad.mean().round(4),' by c:',np.round(bad.reshape(20,512).mean(1),3))
    ang=np.degrees(np.arctan2(a[:,1],a[:,0])); r=np.linalg.norm(a,axis=1)
    for ci in [2,8,16]:
        s=slice(ci*512,(ci+1)*512)
        h,_=np.histogram(ang[s],bins=24,range=(-180,180))
        print(' c',round(cs[ci],2),'r q',np.round(np.percentile(r[s],[5,50,95]),2),'ang hist(15deg)',h)

